def has_cycle_of_length(adj, length, n):
    """Check if graph has a cycle of given length using BFS"""
    from collections import deque

    for start in range(n):
        # BFS to find cycles
        # dist[v] = distance from start
        # parent[v] = parent in BFS tree
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])

        while queue:
            u = queue.popleft()
            if dist[u] >= length:
                continue
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u] and dist[v] >= dist[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len == length:
                        return True
    return False

def has_short_cycle(adj, max_len, n):
    """Check if graph has any cycle of length <= max_len"""
    for length in range(3, max_len + 1):
        if has_cycle_of_length(adj, length, n):
            return True
    return False

def is_3_colorable(adj, n):
    """Check if graph is 3-colorable using backtracking"""
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for u in adj[v]:
                if u < v and colors[u] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

