    """Check if graph is 3-colorable using backtracking with MRV heuristic"""
    colors = [-1] * n
    domains = [set(range(3)) for _ in range(n)]

    def get_valid_colors(v):
        valid = set(range(3))
        for u in adj[v]:
            if colors[u] != -1:
                valid.discard(colors[u])
        return valid

    def select_variable():
        # MRV: choose uncolored vertex with fewest valid colors
        best = -1
        best_count = 4
        for v in range(n):
            if colors[v] == -1:
