            if dist[u] >= 6:
                continue
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u] and dist[v] >= dist[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 7:
                        return False, cycle_len
    return True, None

# Try a specific bipartition
random.seed(42)
vertices = list(range(n))
random.shuffle(vertices)
split = 9
a_set = set(vertices[:split])
b_set = set(vertices[split:])

adj_a = {v: set() for v in a_set}
adj_b = {v: set() for v in b_set}
edges = set()

all_possible = [(a, b) for a in a_set for b in b_set]
random.shuffle(all_possible)

for a, b in all_possible:
    # Check 4-cycle: a and some a' both connect to b and some b'
    creates_4cycle = False
    for a2 in adj_a[a]:
        if b in adj_b[a2]:
            creates_4cycle = True
            break
    if creates_4cycle:
        continue

    # Check 6-cycle: path of length 5 from a to b
    dist = {a: 0}
    queue = deque([a])
    found = False
    while queue:
        u = queue.popleft()
        if dist[u] >= 5:
            continue
        if u in a_set:
            neighbors = adj_a[u]
        else:
            neighbors = adj_b[u]
        for v in neighbors:
            if v not in dist:
                dist[v] = dist[u] + 1
                queue.append(v)
            elif v == b:
                if dist[u] + 2 == 6:
                    found = True
                break
        if found:
            break

    if not found:
        adj_a[a].add(b)
        adj_b[b].add(a)
        edges.add((min(a,b), max(a,b)))

print(f"Edges: {len(edges)}")
